Lemma fast (fx : FPState) R M model s sm cr :
  bregs R -> getr R (reg 11) = Z_to_bv 64 (PM.sr_rem (PM.p_src s)) -> 1 <= len <= PM.sr_rem (PM.p_src s) ->
  st_ok M model s sm cr -> fields_eq s -> PMSP.src_step (PM.p_src s0) (PM.p_src s) sm0 sm -> PM.unread (PM.p_src s) sm = PM.unread (PM.p_src s0) sm0 ->
